public sealed record CloseInvoice(int Id) : ICommand;

public sealed class CloseInvoiceHandler(IInvoiceStore store) : ICommandHandler<CloseInvoice>
{
    public async Task<Result<Unit>> HandleAsync(CloseInvoice command, CancellationToken cancellationToken)
    {
        var invoice = await store.FindAsync(command.Id, cancellationToken);

        if (invoice is null) return Error.NotFound("invoice.missing", $"No invoice {command.Id}.");
        if (invoice.IsClosed) return Error.Conflict("invoice.closed", "Already closed.");

        invoice.Close();

        return Unit.Success;
    }
}

// Cross-cutting work is a behaviour, never repeated in a handler:
public sealed class LoggingBehavior<TRequest, TResponse>(ILogger<TRequest> logger)
    : IPipelineBehavior<TRequest, TResponse> where TRequest : IRequest<TResponse>
{
    public int Order => BehaviorOrder.Logging;

    public async Task<Result<TResponse>> HandleAsync(
        TRequest request, RequestHandlerDelegate<TResponse> next, CancellationToken cancellationToken)
    {
        var result = await next();

        if (result.IsFailure) logger.LogWarning("{Request} failed: {Errors}", typeof(TRequest).Name, result.Errors);

        return result;
    }
}
